  const baseQuote:BudgetQuote={schemaVersion:1,id:budgetQuoteId,projectId:job.projectId,providerId:"sogni",modelId:job.modelId!,operation:job.operation as "anchor"|"take",inputHash,estimateMin:100,estimateMax:200,currency:"USD",unit:"minor_currency",entitlement:"subscription",createdAt:1000,expiresAt:mediaQuote.expiresAt,mediaQuoteId:mediaQuote.id};
