  const reserveSubmission:ReserveSubmission=(tx,current,mediaQuote,_capability,now,context)=>{const execution:BudgetExecution={kind:"media_job",executionId:current.id,operation:current.operation as "anchor"|"take",projectId:current.projectId,idempotencyKey:current.idempotencyKey,requestHash:current.requestHash,executionSemanticHash:context.executionSemanticHash,providerId:current.providerId!,modelId:current.modelId!};tx.registerBudgetExecution(execution);const budgetQuote=tx.getBudgetQuote(context.budgetQuoteId)!,binding=tx.getQuoteAccountBinding(budgetQuote.id)!,evidence=tx.getAccountEvidence(context.accountEvidenceId)!,authorization=tx.getLatestBudgetAuthorization(current.projectId,context.policyId)!;if(binding.unit==="unknown")throw new Error("fixture unit is unknown");const policy=tx.getLatestAccountPolicy({providerId:evidence.providerId,accountId:evidence.accountId,currency:binding.currency,unit:binding.unit});if(!policy||!authorization)throw new Error("fixture authorization missing");const utcDay=new Date(now).toISOString().slice(0,10);const liability=tx.listBudgetLedger({kind:"account_day",utcDay,providerId:evidence.providerId,accountId:evidence.accountId,currency:binding.currency,unit:binding.unit}).reduce((sum,entry)=>sum+entry.reservation.upperEstimate,0);if(liability+(budgetQuote.estimateMax??Number.MAX_SAFE_INTEGER)>policy.dailyCap!)throw new Error("fixture account daily cap exceeded");const reservation:BudgetReservation={schemaVersion:1,id:`reservation-${current.id}`,execution,authorizationRevisionId:authorization.revisionId,policyRevisionId:policy.revisionId,budgetQuoteId:budgetQuote.id,quoteBindingId:binding.id,accountEvidenceId:evidence.id,providerId:evidence.providerId,accountId:evidence.accountId,credentialBindingId:evidence.credentialBindingId,currency:binding.currency,unit:binding.unit,upperEstimate:budgetQuote.estimateMax!,reservedAt:now,utcDay};tx.insertBudgetReservation(reservation);return reservation;};
