  it("keeps one scheduler owner, preserves its heartbeat on a second start, and recovers after SIGKILL",async()=>{const dir=mkdtempSync(join(tmpdir(),"production-worker-owner-"));dirs.push(dir);const script=join(process.cwd(),"scripts/production-worker.mjs");const launch=(workerDataDir=dir)=>spawn(process.execPath,["--import","tsx",script],{cwd:process.cwd(),env:{...process.env,PERABYTE_STUDIO_DATA_DIR:workerDataDir,SOGNI_API_KEY:""},stdio:["ignore","ignore","pipe"]});const waitFor=async(predicate:()=>boolean)=>{const end=Date.now()+8000;while(Date.now()<end){if(predicate())return;await new Promise(resolve=>setTimeout(resolve,50));}throw new Error("Timed out waiting for worker ownership state");};let first=launch();let restarts:ReturnType<typeof launch>[]=[];try{await waitFor(()=>{try{return existsSync(join(dir,"worker-heartbeat.json"));}catch{return false;}});const original=await readFile(join(dir,"worker-heartbeat.json"),"utf8");const originalOwner=await readFile(join(dir,"worker-owner.json"),"utf8");const alias=join(dir,"alias");symlinkSync(dir,alias);const second=launch(alias);let secondError="";second.stderr?.on("data",chunk=>secondError+=chunk.toString());const secondExit=await new Promise<number|null>(resolve=>second.once("exit",code=>resolve(code)));expect(secondExit).toBe(1);expect(secondError).toMatch(/another production worker already owns/i);expect(await readFile(join(dir,"worker-heartbeat.json"),"utf8")).toBe(original);expect(await readFile(join(dir,"worker-owner.json"),"utf8")).toBe(originalOwner);first.kill("SIGKILL");await new Promise(resolve=>first.once("exit",resolve));restarts=[launch(),launch()];await waitFor(()=>restarts.some(child=>child.exitCode===1)&&restarts.some(child=>{try{return JSON.parse(readFileSync(join(dir,"worker-heartbeat.json"),"utf8")).pid===child.pid;}catch{return false;}}));const winners=restarts.filter(child=>child.exitCode===null);expect(winners).toHaveLength(1);first=winners[0]!;expect(JSON.parse(readFileSync(join(dir,"worker-owner.json"),"utf8")).pid).toBe(first.pid);expect(JSON.parse(readFileSync(join(dir,"worker-heartbeat.json"),"utf8")).pid).toBe(first.pid);first.kill("SIGTERM");const gracefulExit=await new Promise<number|null>(resolve=>first.once("exit",code=>resolve(code)));expect(gracefulExit).toBe(0);expect(existsSync(join(dir,"worker-owner.json"))).toBe(false);expect(existsSync(join(dir,"worker-heartbeat.json"))).toBe(false);}finally{if(first.exitCode===null)first.kill("SIGKILL");for(const child of restarts)if(child.exitCode===null)child.kill("SIGKILL");}});
