describe("real combined production budget admission",()=>{
  const scope={kind:"account_day" as const,utcDay:"1970-01-01",providerId:"sogni",accountId:"account-1",currency:"USD",unit:"minor_currency" as const};
  const liability=(store:ReturnType<typeof openProductionStore>)=>{const entries=store.read.listBudgetLedger(scope);const folded=entries.map(entry=>({reservation:entry.reservation,accounting:foldReservation(entry.reservation,entry.events.map(event=>event.evidence))}));return summarizeBudget(folded,scope);};
  const run=(queue:ProductionJobQueue,ctx:ReturnType<typeof setup>,admission:ReturnType<typeof realBudgetAdmission>,provider:ProviderPort)=>new ProductionWorker({queue,providers:{sogni:provider},vault:{putStream:vi.fn()} as unknown as DurableMediaVault,...admission,now:ctx.now}).runOnce();
  const acknowledgingProvider=()=>fakeProvider({submit:vi.fn(async(snapshot)=>({providerRef:`remote-${snapshot.jobId}`,honoredInputs:{...receipt(snapshot.jobId),id:`receipt-${snapshot.jobId}`} }))});
  const submitCountFor=(jobId:string,...providers:ProviderPort[])=>providers.reduce((count,provider)=>count+vi.mocked(provider.submit).mock.calls.filter(([snapshot])=>snapshot.jobId===jobId).length,0);

  it("races, retains unknown actual, then admits on final folded actual",async()=>{
    const ctx=setup();const second=secondProjectQueue(ctx);const firstAdmission=realBudgetAdmission(ctx),secondAdmission=realBudgetAdmission({...ctx,store:second.store,queue:second.queue});const firstProvider=acknowledgingProvider(),secondProvider=acknowledgingProvider();
    await Promise.all([run(ctx.queue,ctx,firstAdmission,firstProvider),run(second.queue,ctx,secondAdmission,secondProvider)]);
    const contenders=[{job:ctx.queue.get("job-1")!,store:ctx.store,admission:firstAdmission,provider:firstProvider},{job:second.queue.get(second.job.id)!,store:second.store,admission:secondAdmission,provider:secondProvider}];
    for(const item of contenders){expect(item.store.read.getBudgetQuote(`budget-${item.job.id}`)?.estimateMax).toBe(200);expect(item.store.read.getQuote(item.job.quoteId!)?.estimateMaxMinor).toBe(200);expect(item.store.read.getLatestBudgetAuthorization(item.job.projectId,"policy-1")?.projectCap).toBeGreaterThanOrEqual(200);expect(item.store.read.getLatestAccountPolicy({providerId:"sogni",accountId:"account-1",currency:"USD",unit:"minor_currency"})?.dailyCap).toBe(300);}
    const winners=contenders.filter(item=>item.store.read.getReservationByExecution(item.job.id)!==null),losers=contenders.filter(item=>item.store.read.getReservationByExecution(item.job.id)===null);
    expect(winners).toHaveLength(1);expect(losers).toHaveLength(1);expect(winners[0]!.store.read.getBudgetExecution(winners[0]!.job.id)).not.toBeNull();expect(winners[0]!.store.read.listJobEvents(winners[0]!.job.id,0).some(event=>event.status==="submitting")).toBe(true);expect(losers[0]!.job).toMatchObject({status:"blocked",errorCode:"BUDGET_BLOCKED"});expect(losers[0]!.store.read.getBudgetExecution(losers[0]!.job.id)).toBeNull();expect(submitCountFor(winners[0]!.job.id,firstProvider,secondProvider)).toBe(1);expect(submitCountFor(losers[0]!.job.id,firstProvider,secondProvider)).toBe(0);expect(liability(ctx.store)).toMatchObject({unresolvedLiability:200,totalLiability:200});

    const winner=winners[0]!,original=winner.store.read.getReservationByExecution(winner.job.id)!;await winner.admission.service.reconcile(original.id,`reconcile-${winner.job.id}-unknown`);
    const unknown=ctx.store.read.listBudgetLedger(scope).find(entry=>entry.reservation.id===original.id)!;expect(foldReservation(unknown.reservation,unknown.events.map(event=>event.evidence))).toMatchObject({knownGrossActual:null,settled:false,unresolvedLiability:200,totalLiability:200});
    const blocked=secondProjectQueue(ctx,"fresh-unknown"),blockedAdmission=realBudgetAdmission({...ctx,store:blocked.store,queue:blocked.queue}),blockedProvider=acknowledgingProvider();await run(blocked.queue,ctx,blockedAdmission,blockedProvider);expect(blocked.queue.get(blocked.job.id)).toMatchObject({status:"blocked",errorCode:"BUDGET_BLOCKED"});expect(blocked.store.read.getBudgetExecution(blocked.job.id)).toBeNull();expect(blocked.store.read.getReservationByExecution(blocked.job.id)).toBeNull();expect(blockedProvider.submit).not.toHaveBeenCalled();expect(liability(ctx.store)).toMatchObject({unresolvedLiability:200,totalLiability:200});

    await winner.admission.service.reconcile(original.id,`reconcile-${winner.job.id}-final-50`);expect(liability(ctx.store)).toMatchObject({knownNetActual:50,unresolvedLiability:0,totalLiability:50});expect(winner.store.read.getBudgetReservation(original.id)?.upperEstimate).toBe(200);
    const admitted=secondProjectQueue(ctx,"fresh-final"),admittedAdmission=realBudgetAdmission({...ctx,store:admitted.store,queue:admitted.queue}),admittedProvider=acknowledgingProvider();await run(admitted.queue,ctx,admittedAdmission,admittedProvider);expect(admitted.queue.get(admitted.job.id)?.status).toBe("running");expect(admitted.store.read.getReservationByExecution(admitted.job.id)?.upperEstimate).toBe(200);expect(liability(ctx.store)).toMatchObject({knownNetActual:50,unresolvedLiability:200,totalLiability:250});expect(vi.mocked(firstProvider.submit).mock.calls.length+vi.mocked(secondProvider.submit).mock.calls.length+vi.mocked(admittedProvider.submit).mock.calls.length).toBe(2);
  });

  it("rolls back execution and reservation with a submitting-event trigger failure",async()=>{
    const ctx=setup();const db=new Database(join(ctx.dir,"production.sqlite"));db.exec("CREATE TRIGGER fail_combined_submission_event BEFORE INSERT ON job_events WHEN NEW.status='submitting' AND NEW.job_id='job-1' BEGIN SELECT RAISE(ABORT, 'injected combined event failure'); END");db.close();
    const admission=realBudgetAdmission(ctx),provider=acknowledgingProvider(),reserve=vi.spyOn(admission.service,"reserveInTransaction");await run(ctx.queue,ctx,admission,provider);
    expect(reserve).toHaveBeenCalledTimes(1);expect(provider.submit).not.toHaveBeenCalled();expect(ctx.store.read.getBudgetExecution("job-1")).toBeNull();expect(ctx.store.read.getReservationByExecution("job-1")).toBeNull();expect(ctx.store.read.listJobEvents("job-1",0).some(event=>event.status==="submitting")).toBe(false);
  });
});

describe("uncertain submission classification (C18-UNCERTAIN-SUBMISSION)",()=>{
  it("lands a mid-submit ECONNRESET fetch failure in submission unknown and never resubmits it",async()=>{const ctx=setup();const cause=Object.assign(new Error("socket hang up"),{code:"ECONNRESET"});const provider=fakeProvider({submit:vi.fn().mockRejectedValue(new TypeError("fetch failed",{cause})),poll:vi.fn(),cancel:vi.fn()});const worker=new ProductionWorker({queue:ctx.queue,providers:{sogni:provider},vault:{putStream:vi.fn()} as unknown as DurableMediaVault,downloadResult:async()=>Readable.from([]),...budgetAdmission(ctx),now:ctx.now});await worker.runOnce();expect(provider.submit).toHaveBeenCalledTimes(1);expect(ctx.queue.get("job-1")).toMatchObject({status:"submission_unknown",errorCode:"SUBMISSION_UNKNOWN",providerRef:null});expect(ctx.queue.get("job-1")?.errorMessage).toContain("automatic resubmission is disabled");ctx.advance(40_000);await expect(worker.runOnce()).resolves.toBe(false);expect(provider.submit).toHaveBeenCalledTimes(1);});
  it("holds a deterministic 400-style provider rejection in the same fail-safe unknown outcome without auto-retry",async()=>{const ctx=setup();const provider=fakeProvider({submit:vi.fn().mockRejectedValue(new ProductionApplicationError("INVALID_INPUT","HTTP 400: the model rejected these parameters.")),poll:vi.fn(),cancel:vi.fn()});const worker=new ProductionWorker({queue:ctx.queue,providers:{sogni:provider},vault:{putStream:vi.fn()} as unknown as DurableMediaVault,downloadResult:async()=>Readable.from([]),...budgetAdmission(ctx),now:ctx.now});await worker.runOnce();expect(provider.submit).toHaveBeenCalledTimes(1);expect(ctx.queue.get("job-1")).toMatchObject({status:"submission_unknown",errorCode:"SUBMISSION_UNKNOWN",providerRef:null});expect(ctx.queue.get("job-1")?.errorMessage).toContain("non-network failure");ctx.advance(40_000);await expect(worker.runOnce()).resolves.toBe(false);expect(provider.submit).toHaveBeenCalledTimes(1);});
  it("keeps user cancellation terminal when the provider would abort after a pre-submission cancel",async()=>{const ctx=setup();ctx.queue.requestCancellation("job-1",1001);const provider=fakeProvider({submit:vi.fn(async()=>{throw new DOMException("This operation was aborted","AbortError");}),cancel:vi.fn(),poll:vi.fn()});const worker=new ProductionWorker({queue:ctx.queue,providers:{sogni:provider},vault:{putStream:vi.fn()} as unknown as DurableMediaVault,now:ctx.now});await worker.runOnce();expect(provider.submit).not.toHaveBeenCalled();expect(provider.cancel).not.toHaveBeenCalled();expect(ctx.queue.get("job-1")).toMatchObject({status:"canceled",errorCode:null});});
  it("treats an abort raised during the provider submit as uncertain rather than canceled",async()=>{const ctx=setup();const controller=new AbortController();const provider=fakeProvider({submit:vi.fn(()=>new Promise<Awaited<ReturnType<ProviderPort["submit"]>>>((_,reject)=>{controller.signal.addEventListener("abort",()=>reject(new DOMException("This operation was aborted","AbortError")),{once:true});})),cancel:vi.fn(),poll:vi.fn()});const worker=new ProductionWorker({queue:ctx.queue,providers:{sogni:provider},vault:{putStream:vi.fn()} as unknown as DurableMediaVault,...budgetAdmission(ctx),now:ctx.now});const running=worker.runOnce(controller.signal);const until=Date.now()+2000;while(!(provider.submit as ReturnType<typeof vi.fn>).mock.calls.length&&Date.now()<until)await new Promise(resolve=>setTimeout(resolve,5));expect(provider.submit).toHaveBeenCalledTimes(1);controller.abort();await running;expect(provider.submit).toHaveBeenCalledTimes(1);expect(ctx.queue.get("job-1")).toMatchObject({status:"submission_unknown",errorCode:"SUBMISSION_UNKNOWN",providerRef:null});expect(provider.cancel).not.toHaveBeenCalled();});
});
